-- Takes the sample website content (scripts/sample-website.mjs) out of the
-- DEMO site again. Generated; run with: npm run db:clean-website
delete from articles where (title, summary) in (('Malipayong Pagsaulog sa Fiesta ni Birhen sa Guadalupe', 'Libolibo ka mga parokyano ang mitambong sa Misa, prosesyon ug sayaw sa pasidungog sa atong patrona.'), ('GKK Birhen sa Fatima: Gibendisyonan ang Bag-ong Kapilya', 'Human sa duha ka tuig nga pagpanginabuhi ug bayanihan, nahuman na ang bag-ong kapilya sa GKK Birhen sa Fatima.'), ('Youth Ministry: Usa ka Adlaw sa Pag-alagad sa Komunidad', 'Kapin 60 ka batan-on ang mitabang sa paglimpyo, pagtanom og kahoy ug pagbisita sa mga tigulang.'), ('Bible Month: Ang Pulong sa Dios sa Matag Panimalay', 'Sulod sa usa ka bulan, ang matag GKK nagbasa sa tibuok Ebanghelyo ni San Marcos.'), ('Ang Unang Kapilya sa Mua-an: Mga Handumanan sa mga Tigulang', 'Gisaysay sa mga tigulang sa parokya kung giunsa pagsugod ang komunidad sa usa ka gamay nga kapilya nga kawayan.'), ('Formation Seminar alang sa mga Lector ug Commentator', '35 ka lector ug commentator gikan sa 12 ka GKK ang mitambong sa usa ka adlaw nga formation.'));
delete from announcements where (title, body) in (('Iskedyul sa mga Misa sa Adlaw sa mga Santos ug Kalag-kalag', 'Nobyembre 1 (Adlaw sa mga Santos): Misa sa 6:00 ug 8:00 sa buntag sa simbahan.
Nobyembre 2 (Kalag-kalag): Misa sa 6:00 sa buntag sa simbahan, ug sa 4:00 sa hapon sa sementeryo publiko.

Ang mga pangalan sa atong mga minahal nga namatay mahimong ihatag sa opisina hangtod Oktubre 31.'), ('Rosaryo sa Oktubre sa Matag GKK', 'Matag gabii sa Oktubre, alas 7, ang imahen sa Birhen moduaw sa usa ka panimalay sa matag GKK alang sa Santo Rosaryo. Pangutan-a ang inyong GKK coordinator sa iskedyul.'), ('Pagpalista sa Bunyag alang sa Disyembre', 'Ang Bunyag sa Disyembre himoon sa Disyembre 5 ug 19. Ipalista ang bata sa opisina dili mosobra sa Nobyembre 28. Dad-a ang birth certificate sa bata ug ang kopya sa kasal sa ginikanan (kung naa). Ang mga ninong ug ninang kinahanglan motambong sa pre-baptismal seminar.'), ('Panawagan: Mga Boluntaryo alang sa Simbang Gabi', 'Nanginahanglan kami og mga usher, choir member ug mga motabang sa pagpangandam sa simbahan alang sa Simbang Gabi (Disyembre 16 hangtod 24). Ipalista ang inyong ngalan sa Parish Pastoral Council o sa opisina.'), ('GKK Assembly sa Ikaduhang Domingo sa Nobyembre', 'Tanang GKK coordinator ug mga opisyal gidapit sa GKK Assembly human sa Misa sa alas 8. Hisgutan ang plano alang sa Adbiyento, ang census sa sunod tuig ug ang Fiesta ni Birhen sa Guadalupe.'), ('Walay Misa sa Kapilya sa Lumot karong Sabado', 'Tungod sa pag-ayo sa atop sa kapilya, walay Misa sa GKK Lumot karong Sabado. Ang mga parokyano gidapit sa Misa sa simbahan sa alas 5 sa hapon.'));
delete from events where (title, description) in (('Pastoral Council Meeting', 'Buwanang miting sa PPC: report sa matag ministry ug plano alang sa Adbiyento.'), ('Seminar sa Pagpangandam sa Kasal', 'Alang sa mga magtiayon nga magpakasal sa simbahan sa sunod tulo ka bulan. Ipalista sa opisina.'), ('Kalag-kalag: Misa sa Sementeryo', 'Misa alang sa tanang kalag sa atong mga minahal nga namatay, inubanan sa bendisyon sa mga lubnganan.'), ('Advent Recollection alang sa mga Ministry', 'Usa ka adlaw sa pag-ampo ug pamalandong alang sa tanang miyembro sa mga ministry ug organisasyon, sa dili pa ang Adbiyento.'), ('Nobena alang sa Birhen sa Guadalupe', 'Siyam ka gabii sa nobena ug Misa, ang matag gabii gipangulohan sa usa ka GKK.'), ('Fiesta ni Birhen sa Guadalupe', 'Misa Concelebrada, prosesyon libot sa plasa ug salo-salo sa tanang GKK.'), ('Simbang Gabi', 'Siyam ka kaadlawon nga Misa sa pagpangandam sa Pasko.'));
delete from history_articles where not is_main and (title, body) in (('Ang Unang Kapilya nga Kawayan', 'Ang mga unang Katoliko nga nanimuyo sa Mua-an nagtukod og usa ka gamay nga kapilya nga kawayan ug nipa duol sa suba. Usa ka pari gikan sa lungsod ang moabot kausa sa usa ka bulan aron magmisa ug magbunyag.

Ang kapilya nahimong tigumanan sa komunidad: dinhi gihimo ang mga nobena, ang katesismo sa mga bata ug ang mga tigum sa barangay.'), ('Ang Pagsugod sa mga GKK', 'Uban sa pagdasig sa Diyosesis, ang mga purok giorganisa ngadto sa mga Gagmayng Kristohanong Katilingban (GKK). Ang matag GKK adunay kaugalingong coordinator ug Bible Sharing matag semana.

Sa 1980, napulo na ka GKK ang aktibo, ug ang matag usa nagsugod sa pagtukod sa kaugalingong kapilya.'), ('Ang Bag-ong Simbahan nga Konkreto', 'Human sa lima ka tuig nga pagpanginabuhi, gibendisyonan ang bag-ong simbahan nga konkreto nga adunay kampanaryo. Ang kampana gihatag sa usa ka pamilya isip pasalamat sa ilang anak nga naayo sa sakit.

Ang karaang kapilya nga kawayan gihimong kapilya sa GKK nga duol sa suba.'), ('Nahimong Quasi-Parish', 'Gideklarar sa Obispo ang Our Lady of Guadalupe isip quasi-parish, nga adunay kaugalingong kura paroko ug parish office. Ang unang Fiesta isip quasi-parish gisaulog uban sa tanang GKK sa Disyembre 12.

Karon, ang parokya adunay kapin 16 ka GKK ug daghang ministry ug organisasyon.'));
update gkks set photo_url = null where photo_url like '%/demo-website/%';
